CREATE TABLE IF NOT EXISTS ducks_coffee_shop_credentials_table (id BIGSERIAL PRIMARY KEY, shop_id BIGINT NOT NULL, login TEXT NOT NULL, "password" TEXT NOT NULL, created_by BIGINT NOT NULL, CONSTRAINT fk_ducks_coffee_shop_credentials_table_shop_id__id FOREIGN KEY (shop_id) REFERENCES ducks_shop_table(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_ducks_coffee_shop_credentials_table_created_by__id FOREIGN KEY (created_by) REFERENCES ducks_admin_table(id) ON DELETE SET NULL ON UPDATE RESTRICT)